(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.15)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.18)*8;
  const wx2 = Math.sin(y*0.025+t*0.4)*6 + Math.cos(x*0.03-t*0.3)*5;
  const wy2 = Math.cos(x*0.025+t*0.35)*6 + Math.sin(y*0.028+t*0.45)*5;
  const sx = x+wx+wx2, sy = y+wy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.9],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.1],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*40, 0.11, 2.1, 0.6],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*50, 0.085, 1.8, 1.3]
  ];
  let aS=0, iS=0, wS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    aS += wave*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    wS += Math.sin(d*f*1.3-t*sp*0.4+2.8)*w*0.5;
  }
  const n = src.length;
  const act=aS/n, inh=iS/n, wav=wS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07+sy*0.05+t*1.6)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.03-ang*5+t*0.8)*0.2;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+wav*0.25)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08;
  const blend = reaction*0.6+cell*0.25+micro*0.15, v=blend*0.5+0.5;
  const pal = [
    [5,12,48],[10,35,85],[15,70,115],[20,115,125],
    [45,155,130],[130,185,100],[200,190,65],
    [215,140,55],[195,85,55],[160,45,60],
    [100,25,55],[45,15,45],[5,12,48]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.18:Math.abs(reaction)>0.4?1.06:0.95;
  const depth=1.0+Math.sin(dist*0.02-t*0.5)*0.08;
  const m = lum*edge*depth;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
